<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --surface: #121a2d;
      --surface-2: #17213a;
      --border: rgba(255, 255, 255, 0.12);
      --text: #f4f7fb;
      --muted: #a7b1c5;
      --accent: #8ab4ff;
      --danger: #ff6b7a;
      --danger-strong: #ff8793;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    html, body {
      min-height: 100%;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(138, 180, 255, 0.18), transparent 32%),
        linear-gradient(180deg, #0a1020 0%, var(--bg) 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: #fff;
      color: #111;
      transform: translateY(-150%);
      transition: transform 160ms ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 5rem 1.25rem 2rem;
    }

    .preview-card {
      width: min(100%, 42rem);
      padding: 1rem;
      border: 1px solid var(--border);
      border-radius: 1.5rem;
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    h1 {
      margin: 0 0 1rem;
      font-size: clamp(1.4rem, 2vw, 2rem);
      line-height: 1.15;
    }

    .preview {
      overflow: hidden;
      border-radius: 1rem;
      background: #0f1628;
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .preview img {
      display: block;
      width: 100%;
      aspect-ratio: 16 / 10;
      object-fit: cover;
      background: #0b1220;
    }

    .preview-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 0.25rem 0.25rem;
      flex-wrap: wrap;
    }

    .preview-meta p {
      margin: 0;
      color: var(--muted);
    }

    button {
      font: inherit;
    }

    .trigger,
    .ghost-button,
    .destructive-button {
      min-height: 2.75rem;
      border: 0;
      border-radius: 999px;
      padding: 0.75rem 1rem;
      cursor: pointer;
      transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease;
    }

    .trigger {
      background: linear-gradient(180deg, #ff7f8a, #e95566);
      color: #fff;
      box-shadow: 0 12px 28px rgba(233, 85, 102, 0.32);
    }

    .ghost-button {
      background: rgba(255, 255, 255, 0.05);
      color: var(--text);
      border: 1px solid rgba(255, 255, 255, 0.1);
    }

    .destructive-button {
      background: linear-gradient(180deg, var(--danger-strong), var(--danger));
      color: #14070a;
      font-weight: 700;
      box-shadow: 0 12px 28px rgba(255, 107, 122, 0.25);
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible,
    .skip-link:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    dialog {
      width: min(100% - 2rem, 30rem);
      border: 1px solid var(--border);
      border-radius: 1.5rem;
      padding: 0;
      color: var(--text);
      background: linear-gradient(180deg, #18223a 0%, #10182a 100%);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(4, 8, 16, 0.72);
      backdrop-filter: blur(6px);
    }

    .dialog-content {
      padding: 1.25rem;
    }

    .dialog-header {
      display: flex;
      align-items: flex-start;
      gap: 0.875rem;
      margin-bottom: 1rem;
    }

    .dialog-icon {
      width: 2.75rem;
      height: 2.75rem;
      flex: none;
      display: grid;
      place-items: center;
      border-radius: 999px;
      background: rgba(255, 107, 122, 0.16);
      color: var(--danger-strong);
      font-size: 1.3rem;
    }

    .dialog-title {
      margin: 0;
      font-size: 1.25rem;
      line-height: 1.2;
    }

    .dialog-body {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      margin-top: 1.5rem;
      flex-wrap: wrap;
    }

    @media (max-width: 30rem) {
      .preview-card {
        padding: 0.75rem;
      }

      .preview-meta {
        align-items: stretch;
      }

      .trigger,
      .ghost-button,
      .destructive-button {
        width: 100%;
      }

      .dialog-actions {
        justify-content: stretch;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main" tabindex="-1">
    <section class="preview-card" aria-labelledby="page-title">
      <h1 id="page-title">Image preview</h1>

      <div class="preview">
        <img
          src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 750'%3E%3Cdefs%3E%3ClinearGradient id='a' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0' stop-color='%23213a63'/%3E%3Cstop offset='0.55' stop-color='%2312172b'/%3E%3Cstop offset='1' stop-color='%23090d18'/%3E%3C/linearGradient%3E%3ClinearGradient id='b' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0' stop-color='%23ffb36d' stop-opacity='0.9'/%3E%3Cstop offset='1' stop-color='%23ff6b7a' stop-opacity='0.15'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1200' height='750' fill='url(%23a)'/%3E%3Ccircle cx='860' cy='180' r='92' fill='url(%23b)'/%3E%3Cpath d='M0 560 C160 490, 260 500, 420 450 C560 408, 730 348, 900 388 C1030 418, 1110 470, 1200 520 L1200 750 L0 750 Z' fill='%23182b48'/%3E%3Cpath d='M0 630 C180 590, 300 600, 450 560 C620 515, 760 470, 930 500 C1060 525, 1130 565, 1200 600 L1200 750 L0 750 Z' fill='%23101931'/%3E%3Ccircle cx='210' cy='220' r='22' fill='%238ab4ff' fill-opacity='0.18'/%3E%3Ccircle cx='290' cy='280' r='12' fill='%238ab4ff' fill-opacity='0.22'/%3E%3Ccircle cx='340' cy='190' r='8' fill='%23ffffff' fill-opacity='0.35'/%3E%3C/svg%3E"
          alt="Stylized landscape preview with a glowing sunset"
        />
      </div>

      <div class="preview-meta">
        <p>Golden retriever sunset.jpg</p>
        <button type="button" class="trigger" id="delete-trigger">
          Delete image
        </button>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-content">
      <div class="dialog-header">
        <div class="dialog-icon" aria-hidden="true">!</div>
        <div>
          <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
          <p class="dialog-body" id="dialog-description">
            This will remove the image from your library. You can&apos;t undo this action.
          </p>
        </div>
      </div>

      <div class="dialog-actions">
        <button type="button" class="ghost-button" id="cancel-button">Cancel</button>
        <button type="button" class="destructive-button" id="confirm-button">Delete</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.getElementById('delete-trigger');
    const cancelButton = document.getElementById('cancel-button');
    const confirmButton = document.getElementById('confirm-button');

    trigger.addEventListener('click', () => {
      dialog.showModal();
      cancelButton.focus();
    });

    cancelButton.addEventListener('click', () => {
      dialog.close('cancel');
    });

    confirmButton.addEventListener('click', () => {
      dialog.close('delete');
    });
  </script>
</body>
</html>
